let state=loadState();
let route='home',routeArg='',searchTerm='',practiceModule='all',practiceLimit=12,showOnlyDue=false,practiceDifficulty='进阶',practiceType='all',practiceSource='all',codingModule='all',codingDifficulty='all',codingTrack='all',codingLanguage='all';
