function loadState(){
  try {return normalizeStudyState(JSON.parse(localStorage.getItem(KEY)||'{}'));}
  catch{return normalizeStudyState();}
}
function saveState(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('无法保存到浏览器，请尝试导出学习记录。');return false;}}
const E=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const pct=(a,b)=>b?Math.round(a/b*100):0;
