const moduleUrl=id=>`#/module/${id}`;
function setRoute(){
  const h=decodeURIComponent(location.hash.replace(/^#\/?/,''))||'home';
  const parts=h.split('/');route=parts[0]||'home';routeArg=parts[1]||'';
  closeKnowledge();
  if(!['home','module','lesson','practice','review','mock','challenges','challenge','sources','search','companies'].includes(route)) route='home';
  if(route==='lesson'&&lessonById[routeArg]){state.lastLesson=routeArg;saveState();}
  if(route==='practice'&&moduleById[routeArg]){practiceModule=routeArg;practiceSource='all';practiceLimit=12;}
  if(route==='practice'&&routeArg==='phone'){practiceSource='phone';practiceModule='all';practiceDifficulty='all';practiceType='all';practiceLimit=12;}
  if(route==='practice'&&routeArg==='weak'){practiceSource='weak';practiceModule='all';practiceDifficulty='all';practiceType='all';practiceLimit=12;}
  if(route==='challenges'&&routeArg==='acm'){codingTrack='acm';codingModule='all';codingDifficulty='all';}
  mobileOpen=false;render();window.scrollTo(0,0);
  if(route==='lesson'){
    const section=parts[2]==='practice'?'exercises':parts[2]==='coding'?'coding':parts[2]?.startsWith('quiz-')?parts[2]:null;
    if(section)document.getElementById(section)?.scrollIntoView({block:'start'});
  }
}
function toast(message){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),3400);}
function currentTitle(){
  if(route==='module')return moduleById[routeArg]?.name||'课程目录';
  if(route==='lesson')return lessonById[routeArg]?.title||'课程';
  return {companies:'秋招投递',home:'学习首页',practice:'专题练习',review:'错题复习',mock:'模拟笔试',challenges:'编程题',challenge:'编程题',sources:'资料来源',search:'搜索结果'}[route]||'学习首页';
}
function navItem(url,name,label,count,active){return `<a class="nav-link ${active?'active':''}" href="${url}" ${active?'aria-current="page"':''}><span class="nav-icon">${icon(name)}</span><span>${E(label)}</span>${count!==undefined?`<span class="nav-count">${E(count)}</span>`:''}</a>`;}
function shell(){
 const moduleActive=route==='module'||route==='lesson';
 app.innerHTML=`<div class="shell"><div class="mobile-shade ${mobileOpen?'open':''}" data-action="close-menu"></div><aside class="sidebar ${mobileOpen?'open':''}"><a class="brand" href="#/home"><div class="brand-mark">${icon('chip')}</div><div>嵌入式秋招学习站<small>MCU / FREERTOS / C & C++</small></div></a><div class="side-scroll"><div class="side-label">STUDY / 学习空间</div>${navItem('#/home','home','学习首页',undefined,route==='home')}${navItem('#/module/c','path','课程路径',undefined,moduleActive)}${navItem('#/practice','practice','专题练习',undefined,route==='practice')}${navItem('#/challenges','code','编程题',undefined,route==='challenges'||route==='challenge')}${navItem('#/review','review','错题与薄弱点',dueCount()||undefined,route==='review')}${navItem('#/mock','clock','模拟笔试',undefined,route==='mock')}${navItem('#/companies','company','秋招投递',undefined,route==='companies')}<details class="nav-modules" ${moduleActive?'open':''}><summary>${icon('book')}<span>知识模块</span></summary>${modules.map(m=>{const ls=lessons.filter(l=>l.module===m.id);return navItem(moduleUrl(m.id),'chip',m.name,`${ls.filter(l=>state.completed[l.id]).length}/${ls.length}`,route==='module'&&routeArg===m.id||route==='lesson'&&lessonById[routeArg]?.module===m.id);}).join('')}</details>${navItem('#/sources','book','资料与备份',undefined,route==='sources')}</div><div class="side-foot">看懂一个知识点，再亲手写出它。<button class="btn link" data-action="export">导出学习记录 ${icon('book')}</button></div></aside><div class="main"><header class="topbar"><button class="mobile-menu" data-action="toggle-menu" aria-label="打开导航">${icon('menu')}</button><span class="top-sub">${E(currentTitle())}</span><div class="search-wrap"><span class="search-icon">${icon('search')}</span><input id="site-search" type="search" placeholder="搜索知识点与题目…" aria-label="搜索课程和题目" value="${E(searchTerm)}"><span class="search-hint">Ctrl K</span></div><button class="btn ghost small top-backup" data-action="export">备份</button></header><main class="content" id="page-content"></main></div></div>`;
 renderMain();
}
function render(){shell();}
function renderMain(preserve=false){const container=document.querySelector('#page-content');if(!container)return;const oldY=window.scrollY;
  let html='';switch(route){case 'companies':html=recruitmentPage();break;case 'home':html=homePage();break;case 'module':html=modulePage(routeArg);break;case 'lesson':html=lessonPage(routeArg);break;case 'practice':html=practicePage();break;case 'review':html=reviewPage();break;case 'mock':html=mockPage();break;case 'challenges':html=challengesPage();break;case 'challenge':html=challengePage(routeArg);break;case 'sources':html=sourcesPage();break;case 'search':html=searchPage();break;default:html=homePage();}
  container.innerHTML=html;if(route==='companies')mountRecruitment();mountStudyPlayers(container);if(preserve)window.scrollTo(0,oldY);
}
function pageHead(label,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${E(label)}</div><h1>${E(title)}</h1><p>${E(description)}</p></div>${action}</div>`;}
function moduleCard(m){const items=chaptersFor(m.id,lessons).flatMap(g=>g.lessons),done=items.filter(l=>state.completed[l.id]).length,next=items.find(l=>!state.completed[l.id])||items[0];return `<a class="module-card" href="${moduleUrl(m.id)}"><div class="module-top"><span class="module-label">${E(m.id.toUpperCase())}</span><span class="progress-note">${done} / ${items.length}</span></div><h3>${E(m.name)}</h3><p>${E(m.description)}</p><div class="progress" aria-label="已学 ${done} / ${items.length} 课"><span style="width:${pct(done,items.length)}%"></span></div><div class="module-next">${done===items.length?'已学完 · 继续巩固':'下一课：'+E(cleanTitle(next.title))}</div></a>`;}
function courseCard(l,index,recommended=null){const done=!!state.completed[l.id],current=!done&&l.id===recommended,codingCount=challenges.filter(c=>c.lesson===l.id||c.relatedLessons?.includes(l.id)).length,mastered=state.mastery[l.id]==='mastered';return `<a class="course-card ${done?'course-done':''} ${current?'course-current':''}" href="${lessonUrl(l.id)}" ${current?'aria-current="step"':''}><span class="course-status" aria-label="${mastered?'已练熟':done?'已学过':current?'推荐学习':'未开始'}">${mastered||done?'✓':current?'●':'○'}</span><span class="course-num">${String(index+1).padStart(2,'0')}</span><div class="course-body"><strong>${E(cleanTitle(l.title))}</strong><p>${E(l.summary)}</p></div><div class="course-meta"><span>${icon('practice')} ${l.quiz.length} 题</span>${codingCount?`<span>${icon('code')} ${codingCount}</span>`:''}<small>${mastered?'已练熟':done?'已学过':current?'推荐下一课':'未开始'}</small></div></a>`;}
function todayPlan(){const date=dayKey();let plan=state.dailyPlans[date];if(!plan){const preferred=['c','stm32','rtos','protocol','ds','os','memory','engineering','cpp','arm','linux','network','project'].flatMap(m=>chaptersFor(m,lessons).flatMap(g=>g.lessons)),last=lessonById[state.lastLesson],l=last&&!state.completed[last.id]?last:preferred.find(l=>!state.completed[l.id])||lessons[0],review=Object.entries(state.answers).filter(([id,a])=>questionById[id]&&a.needsReview&&(!a.due||a.due<=Date.now())).slice(0,2).map(([id])=>id),weak=Object.keys(state.markedWeak).find(id=>state.markedWeak[id]&&lessonById[id])||weakGroups.find(g=>!state.weakMastered[g.id])?.lesson||'c-pointer-change';plan={lesson:l.id,questions:l.quiz.slice(0,3).map(q=>q.id),review,weak};state.dailyPlans[date]=plan;saveState();}return plan;}
function homePage(){const plan=todayPlan(),l=lessonById[plan.lesson]||lessons[0],resume=lessonById[state.lastLesson]||l,m=moduleById[resume.module],items=lessons.filter(x=>x.module===m.id),done=items.filter(x=>state.completed[x.id]).length,chapter=chaptersFor(m.id,lessons).find(g=>g.lessons.some(x=>x.id===resume.id)),events=state.activity.filter(e=>e.day===dayKey()),answered=plan.questions.filter(id=>events.some(e=>e.kind==='answer'&&e.id===id)),reviewed=plan.review.filter(id=>events.some(e=>e.kind==='answer'&&e.id===id)),trained=events.some(e=>e.kind==='answer'&&questionById[e.id]?.lesson.id===plan.weak),marked=Object.keys(state.markedWeak).filter(id=>state.markedWeak[id]&&lessonById[id]),wrong=Object.entries(state.answers).filter(([id,a])=>a.needsReview&&a.reviewReason==='wrong'&&questionById[id]),wrongGroups=[...new Set(wrong.map(([id])=>questionById[id].lesson.id))].slice(0,3),backupOld=state.activity.length&&(!state.lastBackupAt||Date.now()-state.lastBackupAt>7*86400000);
 const task=(number,title,detail,url,finished)=>`<a class="today-task ${finished?'task-done':''}" href="${url}"><span class="task-check" aria-label="${finished?'已完成':'待完成'}">${finished?'✓':'○'}</span><span class="task-number">${number}</span><div><strong>${E(title)}</strong><small>${E(detail)}</small></div><span class="task-state">${finished?'已完成':'去完成 →'}</span></a>`;
 return `${pageHead('TODAY / '+dayKey(),'今天 3 件事','看懂一个知识点，再亲手写出它。按自己的节奏，一次推进一点。')}
 <section class="resume-card panel"><div><div class="eyebrow">继续学习 / ${E(m.name)} · ${E(chapter?.title||'课程路径')}</div><h2>${E(cleanTitle(resume.title))}</h2><div class="resume-progress"><div class="progress"><span style="width:${pct(done,items.length)}%"></span></div><span>${done} / ${items.length} 课已学</span></div></div><a class="btn primary" href="${lessonUrl(resume.id)}">${state.completed[resume.id]?"回顾这一课":"继续学习"} →</a></section>
 <div class="dashboard-grid"><section class="panel task-panel"><header class="panel-title"><span class="eyebrow">TODAY / 今日任务</span><small>任务按今天的实际操作更新</small></header>${task('01','学这一课：'+cleanTitle(l.title),'参考 15–25 分钟；看懂后再标记学过',lessonUrl(l.id),!!state.completed[l.id])}${task('02',`完成本课 ${plan.questions.length} 道随堂题`,`已作答 ${answered.length} / ${plan.questions.length}；答案与解析默认隐藏`,lessonUrl(l.id)+'/practice',answered.length===plan.questions.length)}${plan.review.length?task('03',`复习 ${plan.review.length} 道到期题`,`已复习 ${reviewed.length} / ${plan.review.length}`, '#/review',reviewed.length===plan.review.length):task('03','练一个薄弱知识点',cleanTitle(lessonById[plan.weak]?.title||'指针基础'),lessonUrl(plan.weak)+'/practice',trained)}</section>
 <section class="panel weakness-panel"><header class="panel-title"><span class="eyebrow">FOCUS / 薄弱点</span><a href="#/review">查看全部 →</a></header><div class="weakness-row"><strong>主动标记不熟练</strong><span>${marked.length} 节课 · ${weakGroups.filter(g=>!state.weakMastered[g.id]).length} 个截图考点待练</span></div>${marked.slice(0,2).map(id=>`<a class="weakness-link" href="${lessonUrl(id)}">${E(cleanTitle(lessonById[id].title))}<span>待练</span></a>`).join('')}${!marked.length?'<a class="weakness-link" href="#/practice/weak">我的笔试薄弱题<span>原题 + 变式</span></a>':''}<div class="weakness-row"><strong>实际答错待复习</strong><span>${wrong.length} 题</span></div>${wrongGroups.map(id=>{const qs=lessonById[id].quiz,submitted=qs.filter(q=>state.answers[q.id]?.submitted||state.answers[q.id]?.reviewReason==='wrong'),miss=qs.filter(q=>state.answers[q.id]?.wrong&&(state.answers[q.id]?.submitted||state.answers[q.id]?.reviewReason==='wrong'));return `<a class="weakness-link" href="${lessonUrl(id)+'/practice'}">${E(cleanTitle(lessonById[id].title))}<span>答错 ${miss.length} / ${submitted.length} 题</span></a>`;}).join('')}${!wrong.length?'<p class="quiet-note">还没有实际答错的记录。未作答和查看解析不计为答错。</p>':''}</section></div>
 <div class="personal-stats"><span><b>${completedCount()}</b> 课已学</span><span><b>${answeredCount()}</b> 题已作答</span><span><b>${Object.values(state.answers).filter(a=>a.independentCorrect).length}</b> 题最近一次独立答对</span><a href="#/sources">${icon('book')} 备份与资料</a></div>
 ${backupOld?'<section class="backup-notice"><span>学习记录保存在本机，建议每周留一份备份。</span><button class="btn ghost" data-action="export">导出今日备份</button></section>':''}
 <section class="map-section"><div class="section-head"><div><span class="eyebrow">LEARNING MAP / 知识地图</span><h2>按目标安排学习顺序</h2></div><a href="#/challenges/acm">从输入输出练 ACM →</a></div>${moduleTiers.map(([title,ids])=>`<div class="map-tier"><h3>${title}</h3><div class="module-grid">${ids.map(id=>moduleCard(moduleById[id])).join('')}</div></div>`).join('')}</section>
 <details class="foundation-entry"><summary>不认识 sizeof、&amp;、*？展开从零开始的学习路线</summary>${beginnerGuide({compact:true})}</details><div class="study-shortcuts"><a href="#/practice/phone">手机笔试复述 · 33 题</a><a href="#/practice/weak">截图薄弱题 · 32 题</a><a href="#/companies">秋招投递计划</a></div>`;
}
function modulePage(id){const m=moduleById[id];if(!m)return notFound();const groups=chaptersFor(id,lessons),items=groups.flatMap(g=>g.lessons),done=items.filter(l=>state.completed[l.id]).length,next=items.find(l=>!state.completed[l.id]),fits=l=>courseFilter==='all'||courseFilter==='unfinished'&&!state.completed[l.id]||courseFilter==='coding'&&challenges.some(c=>c.lesson===l.id||c.relatedLessons?.includes(l.id));let index=0;return `${pageHead('COURSE PATH / '+id.toUpperCase(),m.name,'按知识依赖一步步学。每课讲解下方就是练习，前置知识只提醒，不锁课。',`<span class="badge done">已学 ${done} / ${items.length}</span>`)}<div class="progress module-progress"><span style="width:${pct(done,items.length)}%"></span></div><div class="filters path-filters" role="group" aria-label="筛选课程">${[['all','全部'],['unfinished','未完成'],['coding','有编程题']].map(([v,t])=>`<button class="pill ${courseFilter===v?'active':''}" data-action="course-filter" data-value="${v}" aria-pressed="${courseFilter===v}">${t}</button>`).join('')}<span>✓ 已学过　● 推荐下一课　○ 未开始</span></div><div class="learning-path">${groups.map((g,j)=>{const complete=g.lessons.every(l=>state.completed[l.id]),visible=g.lessons.filter(fits);const start=index;index+=g.lessons.length;if(!visible.length)return '';return `<details class="path-chapter" ${complete?'':'open'}><summary><span class="chapter-number">${String(j+1).padStart(2,'0')}</span><strong>${E(g.title)}</strong><span>${g.lessons.filter(l=>state.completed[l.id]).length} / ${g.lessons.length} 已学</span></summary><div class="course-list">${visible.map(l=>courseCard(l,start+g.lessons.indexOf(l),next?.id)).join('')}</div></details>`;}).join('')||'<p class="empty">当前筛选没有课程，可以切回全部。</p>'}</div><details class="foundation-entry"><summary>这个模块从哪里开始？</summary>${id==='c'?beginnerGuide():modulePrimer(id)}</details>`;}

function notFound(){return `<div class="empty"><div class="big">◇</div>没有找到这一页。<p><a href="#/home">返回首页</a></p></div>`;}
function topicNeedsHelp(lessonId){const attempts=state.activity.filter(e=>e.kind==='answer'&&questionById[e.id]?.lesson.id===lessonId).slice(-2);return attempts.length===2&&attempts.every(e=>!e.correct);}
function logActivity(kind,id,extra={}){state.activity.push({kind,id,day:dayKey(),at:Date.now(),...extra});}
function mountStudyPlayers(container){mountPlayers(container,{onRecord(key,record){const old=state.animationRecords[key]||{predictions:{}};state.animationRecords[key]={...old,viewed:old.viewed||!!record.viewed,lastViewedAt:Date.now(),predictions:{...old.predictions,...(record.prediction?{[record.prediction.step]:record.prediction}:{})}};saveState();}});}
function prerequisiteBlock(l){const ids=prerequisiteIds[l.id]||[];return ids.length?`<section class="lesson-prerequisites"><span class="eyebrow">BEFORE / 先会这些更容易</span><div>${ids.map(id=>`<a href="${lessonUrl(id)}"><span>${state.completed[id]?'✓ 已学':'○ 未学'}</span>${E(cleanTitle(lessonById[id].title))}</a>`).join('')}</div><small>可以直接学本课；卡住时再回来补。</small></section>`:'';}
function oralBlock(l){const g=guidance[l.id],t=tutorialFor(l);return `<section class="oral-block"><span class="eyebrow">INTERVIEW / 用自己的话讲清楚</span><h2>面试时怎么答</h2><p>${E(g?.oral||l.summary+' '+(t?.steps||l.points).join(' '))}</p><details><summary>练习表达 · 先自己讲，再核对</summary><p>先说概念，再举一个最小例子，最后交代适用条件和常见错误。可以对照本课结论检查有没有遗漏。</p></details>${g?.terms?.length?`<details class="term-glossary"><summary>术语不熟？展开白话解释</summary><dl>${g.terms.map(([term,meaning])=>`<div><dt>${E(term)}</dt><dd>${E(meaning)}</dd></div>`).join('')}</dl></details>`:''}</section>`;}
function lessonNotes(l){return `<section class="lesson-notes"><label for="personal-notes-${l.id}"><span class="eyebrow">NOTES / 我的理解</span><h2>用自己的话讲一遍</h2></label><p>这节课解决了什么？哪一步还不懂？写下自己的例子。</p><textarea id="personal-notes-${l.id}" data-note="${l.id}" placeholder="例如：p 保存地址，*p 才访问地址对应的内容…">${E(state.notes[l.id]||'')}</textarea><div class="mastery-actions"><span>当前：${state.mastery[l.id]==='mastered'?'已练熟':state.completed[l.id]?'学过待练':'未学'}</span><button class="btn ghost" data-action="mark-weak" data-id="${l.id}" aria-pressed="${!!state.markedWeak[l.id]}">${state.markedWeak[l.id]?'已标记不熟练':'标记不熟练'}</button><button class="btn soft" data-action="mastery" data-id="${l.id}" aria-pressed="${state.mastery[l.id]==='mastered'}">${state.mastery[l.id]==='mastered'?'已练熟 · 改为待练':'我已能独立解释和做题'}</button></div></section>`;}
function closeKnowledge(){const overlay=document.querySelector('#knowledge-overlay');if(!overlay)return;overlay.remove();document.body.style.overflow='';document.querySelector('.shell')?.removeAttribute('inert');activeDrawer=null;drawerReturn?.focus?.();drawerReturn=null;}
function openKnowledge(id,trigger){const item=questionById[id]||writtenQuestions.find(q=>q.id===id)||challenges.find(q=>q.id===id);if(!item)return;const l=typeof item.lesson==='object'?item.lesson:lessonById[item.lesson];if(!l)return;closeKnowledge();drawerReturn=trigger;activeDrawer=id;const rec=state.answers[id]||{};if(questionById[id])state.answers[id]={...rec,...(!rec.revealed?{assisted:true}:{}),knowledgeViewed:true};saveState();const model=modelForLesson(l.id,true),g=guidance[l.id];const overlay=document.createElement('div');overlay.id='knowledge-overlay';overlay.className='knowledge-overlay';overlay.innerHTML=`<div class="knowledge-shade" data-action="close-knowledge"></div><section class="knowledge-drawer" role="dialog" aria-modal="true" aria-labelledby="knowledge-title"><header><span class="eyebrow">KNOWLEDGE / 随时补基础</span><button class="btn ghost" data-action="close-knowledge" aria-label="关闭相关知识点">${icon('close')} 关闭</button></header><div class="knowledge-body"><h2 id="knowledge-title">${E(cleanTitle(l.title))}</h2><p class="drawer-purpose">这里使用独立例子补概念，不演算当前题。关闭后保留你的作答。</p><div class="drawer-conclusion"><span class="eyebrow">一句话先懂</span><p>${E(g?.conclusion||l.summary)}</p></div>${g?.terms?.length?`<details class="drawer-terms"><summary>我还不懂这些符号与术语</summary><dl>${g.terms.map(([a,b])=>`<div><dt>${E(a)}</dt><dd>${E(b)}</dd></div>`).join('')}</dl></details>`:''}${model?playerMarkup(model,'drawer-'+id,{predict:false}):`<section class="drawer-basics"><h3>本课规则与适用条件</h3><ul>${l.points.map(point=>`<li>${E(point)}</li>`).join('')}</ul><h3>从这几个问题开始</h3><p>${E(helpFor(item,l).hint)}</p><p>${E(helpFor(item,l).thinking)}</p><p>试着用一个最小例子验证规则，再回到题目检查它的适用条件。</p></section>`}${prerequisiteBlock(l)}</div><footer><button class="btn primary" data-action="close-knowledge">回到题目继续做</button><a href="${lessonUrl(l.id)}">进入完整课程 →</a></footer></section>`;document.body.append(overlay);document.body.style.overflow='hidden';document.querySelector('.shell')?.setAttribute('inert','');mountStudyPlayers(overlay);overlay.querySelector('button[data-action=close-knowledge]')?.focus();}
function lessonPage(id){
 const l=lessonById[id];if(!l)return notFound();
 const m=moduleById[l.module],path=chaptersFor(l.module,lessons).flatMap(g=>g.lessons),i=path.indexOf(l),prev=path[i-1],next=path[i+1];
 const relevant=challenges.filter(c=>c.lesson===id||c.relatedLessons?.includes(id));
 const written=writtenQuestions.filter(q=>q.lesson===id),basic=l.quiz.filter(q=>!q.difficulty),advanced=l.quiz.filter(q=>q.difficulty);
 const diagram=hasWalkthrough(l)||l.visual;
 const selected=relevant.find(c=>c.id===lessonCodeChoice[id])||relevant.find(c=>c.track==='basics')||(l.beginner?relevant[0]:relevant.find(c=>c.level!=='入门')||relevant[0]);
 const refs=l.refs||sources.filter(s=>l.module==='c'?s.name.includes('N1570')||s.name.includes('AAPCS'):l.module==='cpp'?s.name.includes('C++'):['stm32','protocol','project'].includes(l.module)?s.name.includes(l.id==='p-spi'?'AN5543':'STM32'):l.module==='rtos'||l.module==='os'?s.name.includes('FreeRTOS'):l.module==='arm'?s.name.includes('AAPCS')||s.name.includes('Cortex'):l.module==='memory'?s.name.includes('AAPCS')||s.name.includes('STM32'):false);
 const total=l.quiz.length+written.length+relevant.length;
 return `<div class="crumb"><a href="#/home">学习工作台</a> / <a href="${moduleUrl(m.id)}">${E(m.name)}</a> / ${E(l.title)}</div>
 <header class="lesson-heading"><div><div class="eyebrow">${E(m.name)} · ${E(l.level)}</div><h1>${E(l.title)}</h1><p>${E(l.summary)}</p></div></header>
 <p class="inline-lesson-note">讲解下方就是对应练习，直接向下阅读和作答 · 本课 ${total} 道练习</p>
 <div class="lesson-layout lesson-reading-view inline-lesson"><article class="article panel">${beginnerSequence(l)}
 <div class="lesson-text" data-knowledge="basics">
 ${prerequisiteBlock(l)}${explanation(l)}${modelForLesson(id)?`<h2 id="diagram">把代码一步一步执行</h2>${playerMarkup(modelForLesson(id),"lesson-"+id)}`:""}${oralBlock(l)}<h2 id="concept">关键结论与适用条件</h2>${hasBeginnerNotes(l)?'<details class="advanced-reasoning"><summary>展开笔试规则与平台条件</summary>':''}<ol>${l.points.map(p=>`<li>${E(p)}</li>`).join('')}</ol>${hasBeginnerNotes(l)?'</details>':''}
 </div>
 <section id="exercises" class="lesson-practice-view inline-practice" aria-label="基础随堂练习">
 ${basic.length?`<section id="quiz" class="exercise-group"><div class="exercise-intro"><h2>随堂练习 · 基础巩固 <span>${basic.length} 题</span></h2><p>用刚才的知识作答，不会时再查看解析。</p></div>${basic.map((q,j)=>quizCard(q,j)).join('')}</section>`:''}
 </section>
 <div class="lesson-text lesson-application" data-knowledge="application">
 ${diagram&&!modelForLesson(id)?`<h2 id="diagram">图解推演</h2>${hasWalkthrough(l)?renderWalkthrough(l,visualStep[id]||0,spiMode):visual(l)}`:''}
 ${l.code?`<h2 id="example">代码示例</h2><pre class="codeblock"><code>${E(l.code)}</code></pre>`:''}${workedExample(l)}
 </div>
 ${advanced.length+written.length?`<section id="written" class="exercise-group inline-practice"><div class="exercise-intro"><h2>随堂练习 · 进阶笔试 <span>${advanced.length+written.length} 题</span></h2><p>结合上面的原理与例题，练习代码阅读、推导和找错。</p></div>${advanced.map((q,j)=>quizCard(q,j+basic.length)).join('')}${written.map((q,j)=>writtenCard(q,j+basic.length+advanced.length,state.drafts[q.id])).join('')}</section>`:''}
 ${selected?`<section id="coding" class="inline-practice"><div class="exercise-intro"><h2>随堂练习 · 编程 <span>${relevant.length} 题</span></h2><p>把本课知识写成代码，题目和编辑区就在这里。</p></div><div class="coding-picker"><label for="lesson-coding-select">选择本课题目</label><select id="lesson-coding-select" data-lesson="${id}">${relevant.map((c,j)=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${j+1}. ${E(c.title)} · ${E(c.level)}</option>`).join('')}</select></div>${codingWorkbench(selected,state.drafts[selected.id])}</section>`:''}
 ${lessonNotes(l)}${refs.length?`<details id="references" class="lesson-sources lesson-text"><summary>参考资料 · 需要时核对原理</summary><div class="lesson-refs">${refs.map(x=>`<a href="${E(x.url)}" target="_blank" rel="noopener noreferrer">${E(x.name)}</a>`).join('')}</div></details>`:''}
 </article></div>
 <div class="lesson-nav"><a class="btn ghost" href="${prev?lessonUrl(prev.id):moduleUrl(l.module)}">← ${prev?E(prev.title):'返回目录'}</a><button class="btn ${state.completed[id]?'ghost':'primary'}" data-action="complete" data-id="${id}">${state.completed[id]?'已学过 · 取消标记':'标记学过'}</button><a class="btn ghost" href="${next?lessonUrl(next.id):moduleUrl(l.module)}">${next?E(next.title):'返回目录'} →</a></div>`;
}
function quizCard(q,j,{mockMode=false}={}){
 const lesson=questionById[q.id].lesson,rec=mockMode?null:state.answers[q.id],selected=mockMode?mock?.choices[q.id]:rec?.choice,revealed=mockMode?mock?.finished:rec?.revealed,isCorrect=selected===q.answer,help=helpFor(q,lesson),level=rec?.helpLevel||0;
 const misconception=selected!==undefined&&selected!==q.answer?help.wrong?.[selected]:null;
 const result=revealed?`<div class="quiz-answer"><div class="answer-section"><span class="eyebrow">01 / 你的作答</span><p>${selected===undefined?'未提交答案，主动查看解析':`${letter(q,selected)} · ${E(q.options[selected])}`}</p>${selected!==undefined&&!isCorrect?`<strong class="answer-wrong">${E(misconception||'这个选项与本题条件不符，请按下面的判断依据逐步核对。')}</strong>`:''}</div><div class="answer-section"><span class="eyebrow">02 / 正确答案</span><p><strong>正确答案：${letter(q,q.answer)} · ${E(q.options[q.answer])}</strong></p></div><div class="answer-section"><span class="eyebrow">03 / 为什么</span><p><b>判断依据：</b></p>${q.steps?`<ol>${q.steps.map(x=>`<li>${E(x)}</li>`).join('')}</ol>`:`<p>${E(q.explain)}</p>`}${answerTrace(q)}${help.wrong?`<details><summary>逐项辨析 · 为什么其他选项不对</summary><ul>${optionLayouts.get(q.id).map(k=>`<li><b>${letter(q,k)}：</b>${E(k===q.answer?q.explain:help.wrong[k]||q.explain)}</li>`).join('')}</ul></details>`:''}</div>${!mockMode&&modelForLesson(lesson.id)?`<details class="answer-player"><summary>用动画重新推演本课例子${help.errorStep!==undefined&&!isCorrect?' · 定位可能混淆的一步':''}</summary>${playerMarkup(modelForLesson(lesson.id),'answer-'+q.id+'-'+(rec?.lastAttemptAt||0),{predict:false,startStep:selected!==undefined&&!isCorrect?help.errorStep||0:0})}</details>`:''}${relatedReasoning(lesson)}<a href="${lessonUrl(lesson.id)}">回到对应课程：${E(cleanTitle(lesson.title))} →</a></div>`:'';
 return `<section class="quiz-card" id="quiz-${q.id}" tabindex="-1"><div class="quiz-head"><span class="quiz-num">${j+1}</span><span class="quiz-type">单选题 · ${E(difficulty(q))} · ${E(moduleById[lesson.module].name)} / ${E(cleanTitle(lesson.title))}</span>${!mockMode?`<button class="btn link knowledge-trigger" data-action="knowledge" data-id="${q.id}">${icon('book')} 相关知识点</button>`:''}</div>${!mockMode&&((rec?.errorRun||0)>=2||topicNeedsHelp(lesson.id))&&!revealed?`<div class="concept-nudge">这个知识点最近几次作答有困难。<button class="btn link" data-action="knowledge" data-id="${q.id}">先补一下基础</button>，也可以继续尝试。</div>`:''}<div class="quiz-workspace"><div class="quiz-question"><div class="quiz-prompt">${E(q.prompt)}</div>${q.batch?`<p class="source-note">${E(q.source)}${q.original?' · 保留核心题干与选项':q.batch==='weak'?'':' · 题干与选项重新编写'}</p>`:''}${q.originNote?`<p class="source-note">${E(q.originNote)}</p>`:''}${q.code?`<pre class="codeblock"><code>${E(q.code)}</code></pre>`:''}<div class="options" role="group" aria-label="第 ${j+1} 题选项">${optionLayouts.get(q.id).map((k,displayIndex)=>`<button class="option ${selected===k?'selected':''} ${revealed&&k===q.answer?'correct':''} ${revealed&&selected===k&&k!==q.answer?'wrong':''}" data-action="${mockMode?'mock-choice':'choose'}" data-id="${q.id}" data-choice="${k}" aria-pressed="${selected===k}" ${revealed?'disabled':''}><span class="letter">${'ABCD'[displayIndex]}</span><span>${E(q.options[k])}</span>${revealed&&k===q.answer?'<span class="option-status">✓ 正确</span>':revealed&&selected===k?'<span class="option-status">× 答错</span>':''}</button>`).join('')}</div>${!mockMode?`<div class="quiz-actions"><button class="btn primary" data-action="submit-answer" data-id="${q.id}" ${selected===undefined||revealed?'disabled':''}>提交答案</button><button class="btn ghost" data-action="mark-weak" data-id="${lesson.id}" aria-pressed="${!!state.markedWeak[lesson.id]}">${state.markedWeak[lesson.id]?'已标记不熟练':'标记不会'}</button>${revealed?`<span class="quiz-feedback ${rec?.submitted?(isCorrect?'good':'bad'):''}">${rec?.submitted?(isCorrect?(rec.assisted?'借助帮助后答对':'回答正确 · 独立作答'):'回答错误，加入错题'):'已查看解析，加入复习'}</span><button class="btn link" data-action="review-reset" data-id="${q.id}">重新作答</button>`:''}</div>`:''}</div>${!mockMode&&!revealed?`<aside class="quiz-help"><span class="eyebrow">HELP / 逐级求助</span><p>卡住时先找概念，再尝试推导。</p><button class="help-button" data-action="question-help" data-level="1" data-id="${q.id}" aria-expanded="${level>=1}"><span>01</span> 提示 · 看考什么</button>${level>=1?`<div class="help-text">${E(help.hint)}</div>`:''}<button class="help-button" data-action="question-help" data-level="2" data-id="${q.id}" aria-expanded="${level>=2}"><span>02</span> 思路 · 怎么开始</button>${level>=2?`<div class="help-text">${E(help.thinking)}</div>`:''}<button class="help-button" data-action="reveal" data-id="${q.id}"><span>03</span> 不会？查看解析</button><small>求助会记为“借助帮助”，用于安排复习。</small>${rec?.assisted?'<span class="badge">本次借助帮助</span>':''}</aside>`:''}</div>${result}</section>`;
}
