function practicePage(){
 const inModule=item=>practiceModule==='all'||lessonById[item.lesson]?.module===practiceModule;
 const fits=item=>(practiceDifficulty==='all'||difficulty(item)===practiceDifficulty)&&(practiceSource==='all'||item.batch===practiceSource);
 const choices=allQuestions.map(q=>({...q,lesson:questionById[q.id].lesson.id})).filter(inModule).filter(fits).sort((a,b)=>Boolean(b.difficulty)-Boolean(a.difficulty));
 const written=writtenQuestions.filter(inModule).filter(fits),coding=challenges.filter(inModule).filter(fits);
 const lists={choice:choices.map(q=>({type:'choice',item:q})),written:written.map(q=>({type:'written',item:q})),coding:coding.map(q=>({type:'coding',item:q}))};
 let items=[];if(practiceType==='all'){const n=Math.max(...Object.values(lists).map(a=>a.length));for(let i=0;i<n;i++)for(const list of Object.values(lists))if(list[i])items.push(list[i]);}else items=lists[practiceType]||[];
 if(practiceSource==='phone')items.sort((a,b)=>a.item.shareOrder-b.item.shareOrder);
 if(practiceSource==='weak')items.sort((a,b)=>a.item.focusOrder-b.item.focusOrder);
 const visible=items.slice(0,practiceLimit);
 return `${pageHead('PRACTICE','专题练习','基础题复习概念，进阶题练推导、改错与边界；编程题练完整实现。解析默认隐藏。')}${practiceSource==='weak'?weakSummary():''}${practiceSource==='phone'?`<div class="panel phone-exam-note"><strong>手机笔试复述 · 内容说明</strong><p>${E(phoneExamNotice)}</p></div>`:''}<div class="practice-toolbar exam-filters"><label>题目来源<select id="practice-source">${[['all','全部题库'],['phone','手机笔试复习 · 33题'],['weak','我的薄弱题 · 原题与变式']].map(([v,t])=>`<option value="${v}" ${practiceSource===v?'selected':''}>${t}</option>`).join('')}</select></label><label>模块<select id="practice-module"><option value="all">全部模块</option>${modules.map(m=>`<option value="${m.id}" ${practiceModule===m.id?'selected':''}>${E(m.name)}</option>`).join('')}</select></label><label>难度<select id="practice-difficulty">${['all','基础','进阶','挑战'].map(x=>`<option value="${x}" ${practiceDifficulty===x?'selected':''}>${x==='all'?'全部难度':x}</option>`).join('')}</select></label><label>题型<select id="practice-type">${[['all','全部题型'],['choice','选择题'],['written','代码阅读 / 填空 / 改错 / 简答'],['coding','编程 / 场景题']].map(([v,t])=>`<option value="${v}" ${practiceType===v?'selected':''}>${t}</option>`).join('')}</select></label><span>共 ${items.length} 题 · 已展示 ${visible.length}</span></div><div class="practice-grid"><div class="practice-list">${visible.map(({type,item},j)=>{const first=practiceSource==='weak'&&(j===0||visible[j-1].item.focusGroup!==item.focusGroup),g=weakGroups.find(g=>g.id===item.focusGroup);return (first?weakGroupHead(g):'')+(type==='choice'?quizCard(item,j):type==='written'?writtenCard(item,j,state.drafts[item.id]):practiceSource==='weak'?codingWorkbench(item,state.drafts[item.id],{inline:true}):challengeMini(item));}).join('')}${practiceLimit<items.length?'<button class="btn ghost" data-action="load-more">加载更多题目 ↓</button>':''}${!items.length?'<div class="empty">此筛选暂无题目，可切换模块、难度或题型。</div>':''}</div><aside class="practice-side panel"><h3>按笔试流程练</h3><p>代码题先逐行计算，改错题说明原因，手写题检查边界与复杂度。不要只核对最后的结果。</p><p>选择题的选项顺序已调整；历史答案与错题记录继续有效。非选择题可保存草稿并按评分点自查。</p><a href="#/challenges" class="btn soft">进入编程题 →</a></aside></div>`;
}
function reviewPage(){const entries=Object.entries(state.answers).filter(([id,a])=>a.needsReview&&questionById[id]).map(([id,a])=>({q:questionById[id],a})),due=entries.filter(x=>!x.a.due||x.a.due<=Date.now()),wrong=entries.filter(x=>x.a.reviewReason==='wrong'),helped=entries.filter(x=>x.a.reviewReason!=='wrong'),marked=Object.keys(state.markedWeak).filter(id=>state.markedWeak[id]&&lessonById[id]),filtered=reviewTab==='wrong'?wrong:reviewTab==='help'?helped:due,groups=[...new Set(filtered.map(x=>x.q.lesson.id))];return `${pageHead('REVIEW / 分清问题，再复习','错题复习','今天到期优先。实际答错、借助帮助和主动标记分别记录；只看解析不计为答错。')}<div class="filters review-tabs" role="group" aria-label="复习分类">${[['due','今天到期',due.length],['wrong','全部错题',wrong.length],['help','借助帮助',helped.length],['marked','主动标记',marked.length+weakGroups.filter(g=>!state.weakMastered[g.id]).length]].map(([v,t,n])=>`<button class="pill ${reviewTab===v?'active':''}" data-action="review-filter" data-value="${v}" aria-pressed="${reviewTab===v}">${t} ${n}</button>`).join('')}</div>${reviewTab==='marked'?`${marked.map(id=>`<div class="review-card panel"><span class="review-symbol">○</span><div class="body"><strong>${E(cleanTitle(lessonById[id].title))}</strong><p>主动标记不熟练 · 可以先补知识，再做随堂题</p></div><a class="btn soft" href="${lessonUrl(id)}">去巩固 →</a></div>`).join('')}${weakSummary()}<a class="btn primary" href="#/practice/weak">练截图原题与同类题 →</a>`:groups.length?groups.map(id=>`<section class="review-group"><div class="section-head"><h2>${E(cleanTitle(lessonById[id].title))}</h2><a href="${lessonUrl(id)}">补知识 →</a></div>${filtered.filter(x=>x.q.lesson.id===id).map(({q,a})=>`<div class="review-card panel"><span class="review-symbol">${a.reviewReason==='wrong'?'×':'○'}</span><div class="body"><strong>${E(q.prompt)}</strong><p>${a.reviewReason==='wrong'?'实际答错':'借助帮助 / 查看解析'} · ${a.due&&a.due>Date.now()?'下次 '+new Date(a.due).toLocaleDateString('zh-CN'):'今天可复习'}</p></div><button class="btn soft" data-action="review-reset" data-id="${q.id}">重新作答 →</button></div>`).join('')}</section>`).join(''):`<div class="empty"><h2>${reviewTab==='due'?'今天暂时没有到期题':'这个分类暂时没有题目'}</h2><p>可以继续课程，也可以训练主动标记的薄弱知识点。</p><a class="btn primary" href="#/practice/weak">薄弱题训练 →</a></div>`}`;}

function mockQuestions(){return modules.map(m=>{const pool=allQuestions.filter(q=>questionById[q.id].lesson.module===m.id&&q.difficulty);const fallback=allQuestions.filter(q=>questionById[q.id].lesson.module===m.id);const pick=pool.length?pool:fallback;return pick[Math.floor(Math.random()*pick.length)];}).filter(Boolean);}
function mockPage(){if(!mock)return `${pageHead('TIMED PRACTICE','模拟笔试','优先抽取进阶题，12 道跨模块选择题，限时 20 分钟；提交后显示分数与逐题解析。')}<div class="mock-intro"><div class="mock-stat"><div><strong>12</strong><br>道题</div><div><strong>20</strong><br>分钟</div><div><strong>12</strong><br>覆盖模块</div></div><p>模拟过程中隐藏答案。你可以跳过不会的题，提交后统一查看解析。</p><button class="btn primary" data-action="mock-start">开始模拟 →</button></div>`;const elapsed=Math.floor((Date.now()-mock.started)/1000),left=Math.max(0,1200-elapsed),min=String(Math.floor(left/60)).padStart(2,'0'),sec=String(left%60).padStart(2,'0');const score=mock.questions.filter(q=>mock.choices[q.id]===q.answer).length;return `${pageHead('TIMED PRACTICE','模拟笔试',mock.finished?'已提交，可以查看逐题解析。':'作答时答案隐藏，结束后统一批改。',`<span class="mock-timer">${mock.finished?'已结束':min+':'+sec}</span>`)}${mock.finished?`<div class="result"><strong>${score} / ${mock.questions.length} 题正确</strong><p>错题可回到对应课程继续练习。本次模拟不覆盖课程中的历史答案。</p></div>`:`<div class="mock-banner"><span>已作答 ${Object.keys(mock.choices).length} / ${mock.questions.length}</span><button class="btn primary small" data-action="mock-finish">交卷并查看解析</button></div>`}${mock.questions.map((q,j)=>quizCard(q,j,{mockMode:true})).join('')}${!mock.finished?`<button class="btn primary" data-action="mock-finish">交卷并查看解析</button>`:'<button class="btn ghost" data-action="mock-reset">再做一次</button>'}`;}
function challengesPage(){
 const items=challenges.filter(c=>(codingModule==='all'||lessonById[c.lesson].module===codingModule)&&(codingDifficulty==='all'||difficulty(c)===codingDifficulty)&&(codingTrack==='all'||c.track==='basics')&&(codingLanguage==='all'||c.language===codingLanguage));
 return `${pageHead('CODING LAB','手写与场景题','基础 ACM 题提供 C（stdio.h）和 C++（iostream）完整程序。先独立作答，只有点击查看答案才展开实现。')}${acmGuide()}<div class="practice-toolbar exam-filters"><label>路线<select id="coding-track"><option value="all" ${codingTrack==='all'?'selected':''}>全部编程题</option><option value="acm" ${codingTrack==='acm'?'selected':''}>基础 ACM · 按序学习</option></select></label><label>语言<select id="coding-language">${[['all','全部语言'],['C11','C · stdio.h'],['C++17','C++ · iostream']].map(([v,t])=>`<option value="${v}" ${codingLanguage===v?'selected':''}>${t}</option>`).join('')}</select></label><label>模块<select id="coding-module"><option value="all">全部模块</option>${modules.map(m=>`<option value="${m.id}" ${codingModule===m.id?'selected':''}>${E(m.name)}</option>`).join('')}</select></label><label>难度<select id="coding-difficulty">${['all','基础','进阶','挑战'].map(x=>`<option value="${x}" ${codingDifficulty===x?'selected':''}>${x==='all'?'全部难度':x}</option>`).join('')}</select></label><span>共 ${items.length} 题</span></div><div class="course-list">${items.map((c,j)=>`<a href="#/challenge/${c.id}" class="course-card"><span class="course-num">${String(j+1).padStart(2,'0')}</span><div class="course-body"><strong>${E(c.title)}</strong><p>${E(moduleById[lessonById[c.lesson].module].name)} · ${E(c.kind)} · ${E(c.prompt)}</p></div><div class="course-side"><span class="badge p1">${E(difficulty(c))}</span><span class="arrow">›</span></div></a>`).join('')}</div>${!items.length?'<div class="empty">此筛选暂无题目，请切换模块、语言或难度。</div>':''}<p class="source-note">站内题干、样例与参考解独立编写，链接用于同类原题练习；原平台题意与约束以原页面为准。站内保存草稿，代码运行与判题在原平台或本地进行。</p>`;
}
